-- Monitor profile selection.
--
-- The profile list is per-host data in conf/monitor_profiles.lua (generated by
-- chezmoi). This file only decides which of them applies, and when.
--
-- Order of precedence:
--   1. $HYPR_MONITOR_PROFILE, if it names a profile
--   2. whatever SUPER + SHIFT + P last cycled to
--   3. auto-detect: first profile whose `requires` outputs are all connected

local profiles = require("conf/monitor_profiles")

local current
local pinned = false

---A requirement matches an output name exactly, or any substring of a monitor
---description. Names must be exact: a substring match would let "DP-1" claim
---"DP-10".
local function is_connected(requirement)
    for _, monitor in ipairs(hl.get_monitors()) do
        if monitor.name == requirement then
            return true
        end
        if monitor.description ~= nil and monitor.description:find(requirement, 1, true) then
            return true
        end
    end
    return false
end

local function by_name(name)
    for _, profile in ipairs(profiles) do
        if profile.name == name then
            return profile
        end
    end
end

local function detect()
    for _, profile in ipairs(profiles) do
        local ok = true
        for _, requirement in ipairs(profile.requires) do
            if not is_connected(requirement) then
                ok = false
                break
            end
        end
        if ok then
            return profile
        end
    end
    return profiles[#profiles]
end

local function apply(profile)
    if profile == nil or profile == current then
        return
    end
    current = profile
    for _, spec in ipairs(profile.monitors) do
        hl.monitor(spec)
    end
    hl.notification.create({ text = "Monitors: " .. profile.name, timeout = 2000, icon = "ok" })
end

local function select()
    if pinned then
        return
    end
    apply(by_name(os.getenv("HYPR_MONITOR_PROFILE") or "") or detect())
end

if #profiles > 0 then
    select()

    -- Hotplug: re-run detection whenever the set of outputs changes. Each added
    -- monitor fires separately, and `apply` is a no-op when the winner is
    -- unchanged, so the churn is harmless.
    hl.on("monitor.added", select)
    hl.on("monitor.removed", select)

    -- Manual override, for profiles auto-detect cannot tell apart. Cycling pins
    -- the choice so the next hotplug event does not undo it.
    hl.bind("SUPER + SHIFT + P", function()
        local index = 1
        for i, profile in ipairs(profiles) do
            if profile == current then
                index = i % #profiles + 1
                break
            end
        end
        pinned = true
        apply(profiles[index])
    end, { description = "Cycle monitor profile" })
end

-- Exposed for debugging: `hyprctl repl 'return require("conf/monitors").current()'`
return {
    current = function()
        return current and current.name or "none"
    end,
}
